import { TabContext, TabList, TabPanel } from "@mui/lab";
import {
  Container,
  Grid,
  styled,
  Tab,
  Box,
  createTheme,
  useMediaQuery,
  Fade,
} from "@mui/material";
import React from "react";
import { useState } from "react";
import ADManagerListDetails from "./ADManagerListDetails";
import { ApiEndpoints } from "src/network/endpoints";
import { axiosInstance } from "src/network/adapter";
import { toastError, toastSuccess } from "src/utils/utils";
import { useEffect } from "react";
import { useParams } from "react-router-dom";
import FallbackSpinner from "src/@core/components/spinner";

const ADManagerList = () => {
  const CustomTab = styled(Tab)(({ theme }) => ({
    fontSize: "16px",
    [theme.breakpoints.down("sm")]: {
      fontSize: "14px",
    },
    [theme.breakpoints.up("md")]: {
      fontSize: "20px",
    },
    [theme.breakpoints.up("lg")]: {
      fontSize: "24px",
    },
    fontWeight: 600,
    lineHeight: "28px",
    textTransform: "capitalize",
    wordBreak: "break-word",
    whiteSpace: "normal",
  }));
  const CustomTabPanel = styled(TabPanel)(({ theme }) => ({
    [theme.breakpoints.down("sm")]: {
      padding: 0,
    },
    [theme.breakpoints.up("sm")]: {
      padding: "25px",
    },
  }));
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("xl"));
  const [value, setValue] = useState("highlights");
  const [loading, setLoading] = useState(false);
  const [subAdditionalFeatures, setSubAdditionalFeatures] = useState([]);
  const [subAdditionalFeaturesList, setSubAdditionalFeaturesList] = useState(
    []
  );
  const { id } = useParams();

  const handleChange = (event, newValue) => {
    setValue(newValue);
  };
  const fetchSubAdditionalFeatures = () => {
    axiosInstance
      .get(ApiEndpoints.SUB_ADDITIONAL_FEATURES.list(id))
      .then((response) => {
        setSubAdditionalFeatures(response.data.data);
        const responseData = response.data.data;
        if (responseData.length > 0) {
          setValue(responseData[0].title);
        }
        responseData.map((item) => {
          fetchSubAdditionalFeaturesList(item.id, item.title);
        });
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  const fetchSubAdditionalFeaturesList = (id, title) => {
    axiosInstance
      .get(ApiEndpoints.SUB_ADDITIONAL_FEATURES_LIST.list(id))
      .then((response) => {
        const responseData = response.data.data;
        setSubAdditionalFeaturesList((prevData) => ({
          ...prevData,
          [title]: responseData,
        }));
      })

      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  useEffect(() => {
    fetchSubAdditionalFeatures();
  }, [id]);

  if (loading) return <FallbackSpinner />;
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{ p: { xs: 5, sm: 10, lg: 15, xl: 20 } }}
        >
          <Grid container>
            {subAdditionalFeatures.length > 0 && (
              <Grid item xs={12}>
                <Box sx={{ width: "100%" }}>
                  <TabContext value={value} sx={{ gap: 40, display: "flex" }}>
                    <Box
                      sx={{
                        borderBottom: 1,
                        borderColor: "divider",
                      }}
                    >
                      <TabList
                        onChange={handleChange}
                        aria-label="lab API tabs example"
                        variant={
                          isMobile
                            ? "scrollable"
                            : subAdditionalFeatures.length >= 7
                            ? "scrollable"
                            : "fullWidth"
                        }
                        sx={{
                          "& .MuiTabs-flexContainer": {
                            display: "flex",
                            // justifyContent: "space-between",
                          },
                        }}
                      >
                        {subAdditionalFeatures?.map((item, index) => (
                          <CustomTab
                            label={item.title}
                            value={item.title}
                            key={index}
                          />
                        ))}
                      </TabList>
                    </Box>
                    {subAdditionalFeatures?.map((item, index) => (
                      <Fade
                        in={value === item.title}
                        timeout={1000}
                        key={index}
                      >
                        <CustomTabPanel value={item.title}>
                          <ADManagerListDetails
                            value={subAdditionalFeaturesList[item.title] || []}
                          />
                        </CustomTabPanel>
                      </Fade>
                    ))}
                  </TabContext>
                </Box>
              </Grid>
            )}
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default ADManagerList;
